  image: { key: "q655_custom", source: "Samir. Barretts esophagus.jpg. Wikimedia Commons. Available from: https://commons.wikimedia.org/wiki/File:Barretts_esophagus.jpg. Public domain. Accessed 3 August 2026.", type: "image" }
